def transform(grid):
    # Two equal-width patterns flank a one-cell divider. Their marked-cell
    # intersection is returned in the task's output color.
    divider = next(c for c in range(len(grid[0]))
                   if grid[0][c] != 0 and all(row[c] == grid[0][c] for row in grid))
    left_width = divider
    right_start = divider + 1
    return [
        [2 if grid[r][c] != 0 and grid[r][right_start + c] != 0 else 0
         for c in range(left_width)]
        for r in range(len(grid))
    ]
